<?php $title='تعریف کالا و موجودی لحظه‌ای'; $lists=lists(); ?>
<div class="card"><form class="searchbar" method="get"><input name="q" placeholder="جستجوی سریع نام، کد یا بارکد" value="<?= e($q) ?>"><button class="btn">جستجو</button><a class="btn light" href="<?= e(base_url('items')) ?>">نمایش همه</a></form></div>
<?php if(can('manage_items')): ?><div class="card"><h2>کالای جدید</h2><form method="post" action="<?= e(base_url('items/save')) ?>" data-autosave="item"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><div class="grid"><div class="col-3"><label>کد کالا</label><input name="sku" required></div><div class="col-3"><label>بارکد</label><input name="barcode"></div><div class="col-6"><label>نام کالا</label><input name="name" required></div><div class="col-3"><label>دسته‌بندی</label><select name="category_id"><option value="">-</option><?php foreach($lists['categories'] as $c): ?><option value="<?= e($c['id']) ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select></div><div class="col-3"><label>واحد</label><select name="unit_id"><option value="">-</option><?php foreach($lists['units'] as $u): ?><option value="<?= e($u['id']) ?>"><?= e($u['name']) ?></option><?php endforeach; ?></select></div><div class="col-3"><label>حداقل موجودی</label><input name="min_stock" type="number" step="0.001" value="0"></div><div class="col-12"><label>توضیحات</label><textarea name="description"></textarea></div></div><button class="btn">ذخیره کالا</button></form></div><?php endif; ?>
<div class="card"><h2>لیست کالاها</h2><div class="table-wrap"><table class="table"><tr><th>نام</th><th>کد</th><th>دسته</th><th>واحد</th><th>موجودی</th><th>حداقل</th><th>بارکد</th><th>آخرین ویرایش</th></tr><?php foreach($rows as $r): ?><tr><td><?= e($r['name']) ?></td><td><?= e($r['sku']) ?></td><td><?= e($r['category_name']) ?></td><td><?= e($r['unit_name']) ?></td><td><span class="badge <?= $r['quantity'] <= $r['min_stock'] ? 'danger':'ok' ?>"><?= e(moneyless_number($r['quantity'])) ?></span></td><td><?= e(moneyless_number($r['min_stock'])) ?></td><td><?= Barcode::svg($r['barcode'] ?: $r['sku'], 45) ?></td><td><?= e(jalali_like_datetime($r['updated_at'])) ?></td></tr><?php endforeach; ?></table></div></div>
